import itertools, sys

# literals: original indices 0,1,2 with sign +/-; aux variables a (index 0), b (index1) with sign +/-

def gen_literal_sets(num_aux):
    lits=[]
    for i in range(3):
        lits.append(('o', i, True))
        lits.append(('o', i, False))
    for j in range(num_aux):
        lits.append(('a', j, True))
        lits.append(('a', j, False))
    return lits

def valid_clause(triple):
    # distinct variables (type,index) no repeat
    vars=set()
    for typ,i,_ in triple:
        if (typ,i) in vars:
            return False
        vars.add((typ,i))
    return True

def eval_clause(triple, orig_assign, aux_assign):
    vals=[]
    for typ,i,sign in triple:
        if typ=='o':
            val=orig_assign[i]
        else:
            val=aux_assign[i]
        if not sign:
